import unittest
from pipeline import bounded_min_pipeline

class TestPipeline(unittest.TestCase):
    def test_pipeline_combines_both_structures(self):
        # feed values through a RingBuffer(3) into a MinStack; report the min
        self.assertEqual(bounded_min_pipeline([9, 4, 7, 2, 5], capacity=3), 2)

    def test_capacity_evicts_early_values(self):
        # capacity 2 keeps only the last two: min(8, 6) == 6, the early 1 is evicted
        self.assertEqual(bounded_min_pipeline([1, 8, 6], capacity=2), 6)

    def test_empty_input(self):
        with self.assertRaises(ValueError):
            bounded_min_pipeline([], capacity=2)

if __name__ == "__main__":
    unittest.main()
